import { test, expect, type Page } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

// Count-day page states (E2E-50). The snapshot tree is generated by the real ingest script (SYNTHETIC fixture) and served by the real server.
// Fault injection (ONE helper, withLive): the server derives `live.state` from the clock and a status file, so the stale / source-down /
// delayed-fallback variants are produced by patching only the unsigned `live` block of the real response.
const DIR = path.resolve('data/generated/countday');
test.describe.configure({ mode: 'serial' });
test.beforeAll(() => {
  fs.rmSync(DIR, { recursive: true, force: true });
  execFileSync(process.execPath, ['--import', 'tsx', 'scripts/countday-ingest.ts', '--state', 'AP', '--source', 'fixture', '--steps', '2', '--acs', '6', '--dir', DIR], { stdio: 'pipe' });
});
test.afterAll(() => { fs.rmSync(DIR, { recursive: true, force: true }); });

async function withLive(page: Page, live: Record<string, unknown>) {
  await page.route('**/api/v1/countday/AP/latest', async (route) => {
    const res = await route.fetch();
    const j = await res.json();
    await route.fulfill({ response: res, json: { ...j, live: { ...j.live, ...live } } });
  });
}
const setLang = (page: Page, lang: 'en' | 'te') => page.addInitScript((l) => { try { localStorage.setItem('pp-lang', l); } catch { /* ignore */ } }, lang);

test('@E2E-50 synthetic data carries an unmistakable badge, a state chip, the banner and a delay line', async ({ page }) => {
  await page.goto('/#/countday');
  await expect(page.getByTestId('countday-synthetic-badge')).toContainText('SYNTHETIC');
  await expect(page.getByTestId('countday-state')).toHaveAttribute('data-live-state', 'synthetic');
  await expect(page.getByTestId('countday-banner')).toContainText('SYNTHETIC');
  await expect(page.getByTestId('countday-delay')).toContainText(/minutes/);
  await expect(page.getByTestId('countday-table')).toBeVisible();
});

test('@E2E-50 verification instructions and the keys route are linked and real', async ({ page, request }) => {
  await page.goto('/#/countday');
  await page.getByTestId('countday-verify').locator('summary').click();
  await expect(page.getByTestId('countday-verify')).toContainText(/Ed25519/);
  const href = await page.getByTestId('countday-keys-link').getAttribute('href');
  expect(href).toBe('/api/v1/countday/keys');
  const keys = await (await request.get(href!)).json();
  expect(keys.keys.length).toBeGreaterThan(0);
  const snap = await page.getByTestId('countday-snapshot-link').getAttribute('href');
  expect((await request.get(snap!)).status()).toBe(200);
});

test('@E2E-50 Telugu: banner from the server in Telugu', async ({ page }) => {
  await setLang(page, 'te');
  await page.goto('/#/countday');
  await expect(page.getByTestId('countday-banner')).toContainText('కృత్రిమ');
  await expect(page.getByTestId('countday-state')).toContainText('కృత్రిమ');
});

const CASES = [
  { state: 'stale', banner: { en: 'This is not live. The feed has not updated for 42 minutes.', te: 'ఇది ప్రత్యక్షం కాదు.' }, delayed: 42 },
  { state: 'source-down', banner: { en: 'The live feed is failing. Figures may be behind.', te: 'ప్రత్యక్ష ఫీడ్ విఫలమవుతోంది.' }, delayed: 7 },
  { state: 'delayed-fallback', banner: { en: 'The live feed is not available. Showing delayed archive figures.', te: 'ప్రత్యక్ష ఫీడ్ అందుబాటులో లేదు.' }, delayed: 180 },
];
for (const c of CASES) {
  test(`@E2E-50 fault injection: ${c.state} is never shown as live and says how late it is`, async ({ page }) => {
    await withLive(page, { state: c.state, delayed_minutes: c.delayed, banner: c.banner });
    await page.goto('/#/countday');
    await expect(page.getByTestId('countday-state')).toHaveAttribute('data-live-state', c.state);
    await expect(page.getByTestId('countday-state')).not.toContainText(/^LIVE$/);
    await expect(page.getByTestId('countday-banner')).toHaveText(c.banner.en);
    await expect(page.getByTestId('countday-delay')).toContainText(`Delayed by ${c.delayed} minutes`);
    await expect(page.getByTestId('countday-delay')).toHaveAttribute('data-delayed-minutes', String(c.delayed));
  });
}

test('@E2E-50 fault injection: a live feed shows no alarm banner and says when it was updated', async ({ page }) => {
  await withLive(page, { state: 'live', delayed_minutes: 1, banner: null });
  await page.goto('/#/countday');
  await expect(page.getByTestId('countday-state')).toContainText('LIVE');
  await expect(page.getByTestId('countday-banner')).toHaveCount(0);
  await expect(page.getByTestId('countday-delay')).toContainText('Updated 1 minutes ago');
});

test('@E2E-50 fault injection: when a refresh fails the last figures stay and the page says they may be behind', async ({ page }) => {
  await page.clock.install();
  await page.goto('/#/countday');
  await expect(page.getByTestId('countday-table')).toBeVisible();
  await page.route('**/api/v1/countday/AP/latest', (r) => r.abort());
  await page.clock.fastForward(16_000);
  await expect(page.getByTestId('countday-refresh-failed')).toBeVisible();
  await expect(page.getByTestId('countday-table')).toBeVisible();
});
